<script setup>
import { computed, ref, watch } from 'vue'

const props = defineProps({ open: Boolean, currentFeature: { type: String, default: 'Command Center' } })
const emit = defineEmits(['close'])
const features = [
  { name: 'Command Center', group: 'Workspace', summary: 'Coordinate the live fleet and review today’s shipment health.', steps: ['Load live shipment and fleet data', 'Identify a shipment trending behind its ETA', 'Open the shipment timeline and review its latest scan', 'Assign a response and monitor the updated route'] },
  { name: 'Shipments', group: 'Workspace', summary: 'Create a shipment and follow it from intake through delivery.', steps: ['Enter an order reference and pickup and delivery locations', 'Choose a carrier and transport mode', 'Create the shipment and generate its tracking record', 'Review milestones and update shipment status'] },
  { name: 'Alerts & Exceptions', group: 'Workspace', summary: 'Triage a delivery exception and track its resolution.', steps: ['Detect a missed ETA or stalled tracking update', 'Review severity, location, and customer impact', 'Choose a recovery action or escalate for approval', 'Resolve the alert and record the outcome'] },
  { name: 'System Rules', group: 'Workspace', summary: 'Preview how operational policy evaluates an event.', steps: ['Select a delay threshold or approval rule', 'Provide a sample shipment event', 'Evaluate the event against the configured policy', 'Review the resulting alert and approval requirement'] },
  { name: 'Copilot Assistant', group: 'Workspace', summary: 'Ask a question about the simulated operation and review a suggested next step.', steps: ['Ask which deliveries need attention', 'Gather shipment, route, and inventory context', 'Generate a prioritized operational answer', 'Review the recommendation before acting'] },
  { name: 'Approvals', group: 'Workspace', summary: 'Review a proposed operational action before it runs.', steps: ['Create a sample route or carrier recommendation', 'Inspect its impact, cost, and supporting signals', 'Approve or reject the recommendation', 'Record the decision in the activity history'] },
  { name: 'Customer Updates', group: 'Workspace', summary: 'Preview a customer notification from a shipment event.', steps: ['Select a shipment milestone or exception', 'Prepare a customer friendly status update', 'Review the message and delivery channel', 'Send the simulated update and log its result'] },
  { name: 'Orders & Dispatch', group: 'Operations', summary: 'Move a sample order through carrier assignment and dispatch.', steps: ['Create an order with a destination and priority', 'Link it to a planned shipment', 'Prepare a carrier assignment and quote', 'Confirm simulated dispatch and review its status'] },
  { name: 'Load Planning', group: 'Operations', summary: 'Build a vehicle load while respecting capacity and delivery needs.', steps: ['Choose an available vehicle and capacity', 'Select compatible shipments for the route', 'Check utilization and stop sequence', 'Save the simulated load plan'] },
  { name: 'Warehouse', group: 'Operations', summary: 'Update stock and preview a replenishment exception.', steps: ['Select a warehouse item and shelf location', 'Enter a stock count and reorder point', 'Evaluate the count for low stock', 'Review the replenishment recommendation'] },
  { name: 'Delivery & ePOD', group: 'Operations', summary: 'Complete a delivery and capture proof of delivery.', steps: ['Open an assigned delivery task', 'Record recipient and delivery condition', 'Capture a signature or photo evidence', 'Submit proof and close the delivery task'] },
  { name: 'Analytics & Reports', group: 'Operations', summary: 'Explore a sample operational report and its key measures.', steps: ['Choose a date range and report view', 'Aggregate delivery, delay, and cost records', 'Compare performance with the previous period', 'Export the simulated report'] },
  { name: 'Returns', group: 'Operations', summary: 'Create a return request and follow its workflow.', steps: ['Select the original order', 'Record the return reason and item condition', 'Review pickup and inspection steps', 'Create the simulated return workflow'] },
  { name: 'Activity Log', group: 'Operations', summary: 'Trace a change across the order and dispatch lifecycle.', steps: ['Choose an order or shipment reference', 'Review recorded status and assignment changes', 'Inspect who made each change and when', 'Filter or export the simulated audit trail'] },
  { name: 'Settings', group: 'Account', summary: 'Preview workspace preferences and profile settings.', steps: ['Choose a workspace color theme', 'Update the display name', 'Review account and organization details', 'Save the simulated preferences'] },
  { name: 'Public Live Tracking', group: 'Customer view', summary: 'Preview the public tracking experience for a customer.', steps: ['Enter a sample tracking number', 'Resolve the shipment’s current milestone', 'Show ETA and recent location updates', 'Display customer safe delivery details'] },
  { name: 'App Tutorial', group: 'Account', summary: 'Walk through the core workspace navigation.', steps: ['Introduce the command center', 'Show where orders and shipments are managed', 'Explain alerts, approvals, and customer updates', 'Finish with operations and account settings'] },
]
const selected = ref(features.find((item) => item.name === props.currentFeature)?.name || 'Command Center')
const step = ref(0)
const active = computed(() => features.find((item) => item.name === selected.value) || features[0])
watch(() => props.currentFeature, (feature) => { if (features.some((item) => item.name === feature)) selected.value = feature })
watch(() => props.open, (open) => { if (open) step.value = 0 })
watch(selected, () => { step.value = 0 })
</script>

<template>
  <div v-if="open" class="simulation-backdrop" role="presentation" @click.self="emit('close')">
    <section class="simulation-dialog" role="dialog" aria-modal="true" aria-labelledby="simulation-title">
      <header class="simulation-header"><div><span class="simulation-label">TEMPORARY FEATURE SIMULATION</span><h2 id="simulation-title">Explore a feature</h2><p>Walk through a sample workflow. Simulated actions do not change live operational records.</p></div><button aria-label="Close simulations" @click="emit('close')">×</button></header>
      <div class="simulation-layout">
        <nav class="simulation-nav" aria-label="Feature simulations"><button v-for="group in ['Workspace','Operations','Customer view','Account']" :key="group" class="simulation-group">{{ group }}</button><button v-for="feature in features" :key="feature.name" class="simulation-option" :class="{ selected: selected === feature.name }" @click="selected = feature.name">{{ feature.name }}</button></nav>
        <div class="simulation-content"><span class="simulation-label">{{ active.group }} · {{ step >= active.steps.length ? 'COMPLETE' : `STEP ${step + 1} OF ${active.steps.length}` }}</span><h3>{{ active.name }}</h3><p>{{ active.summary }}</p><div class="simulation-progress"><i :style="{ width: `${Math.round(step / active.steps.length * 100)}%` }"></i></div><ol><li v-for="(item, index) in active.steps" :key="item" :class="{ done: index < step, current: index === step && step < active.steps.length }"><b>{{ index < step ? '✓' : index + 1 }}</b><span>{{ item }}</span></li></ol><div class="simulation-result" aria-live="polite"><strong>{{ step >= active.steps.length ? 'Simulation complete' : 'Sample scenario' }}</strong><span>{{ step >= active.steps.length ? 'The workflow finished with sample data. Reset it to explore again.' : 'This guided scenario uses sample data and stays inside the simulator.' }}</span></div><footer><button @click="step = 0">Reset</button><button v-if="step < active.steps.length" class="primary" @click="step++">{{ step === active.steps.length - 1 ? 'Complete simulation' : 'Next step' }}</button><button v-else class="primary" @click="step = 0">Run again</button></footer></div>
      </div>
    </section>
  </div>
</template>

<style scoped>
.simulation-backdrop{position:fixed;inset:0;z-index:100;display:grid;place-items:center;padding:1rem;background:rgba(10,20,34,.58);backdrop-filter:blur(3px)}.simulation-dialog{display:flex;flex-direction:column;width:min(980px,96vw);max-height:min(760px,92dvh);overflow:hidden;background:var(--panel);color:var(--text);border:1px solid var(--line);border-radius:16px;box-shadow:0 28px 90px rgba(0,0,0,.35)}.simulation-header{display:flex;justify-content:space-between;gap:1rem;padding:1.15rem 1.35rem;border-bottom:1px solid var(--line)}.simulation-header h2{font-size:1.25rem;margin:.25rem 0}.simulation-header p,.simulation-content>p{margin:.25rem 0;color:var(--text-dim);font-size:.8rem;line-height:1.5}.simulation-header>button{align-self:flex-start;font-size:1.25rem;line-height:1;padding:.3rem .55rem}.simulation-label{font:700 .62rem var(--font-mono);letter-spacing:.08em;color:var(--signal)}.simulation-layout{display:grid;grid-template-columns:235px minmax(0,1fr);min-height:0;flex:1}.simulation-nav{overflow:auto;padding:.65rem;border-right:1px solid var(--line)}.simulation-group{display:block;min-height:0;padding:.6rem .55rem .3rem;border:0;background:none;color:var(--text-dim);font-size:.62rem;text-transform:uppercase;letter-spacing:.08em;cursor:default}.simulation-option{display:block;width:100%;min-height:2.1rem;border:0;text-align:left;background:transparent;padding:.4rem .55rem;font-size:.72rem}.simulation-option.selected{color:var(--signal);background:color-mix(in srgb,var(--signal) 12%,var(--panel));font-weight:700}.simulation-content{overflow:auto;padding:1.5rem clamp(1rem,3vw,2.2rem)}.simulation-content h3{margin:.35rem 0;font-size:1.35rem}.simulation-progress{height:5px;margin:1.2rem 0;background:var(--panel-2);border-radius:99px;overflow:hidden}.simulation-progress i{display:block;height:100%;background:var(--signal);transition:width .2s}.simulation-content ol{display:grid;gap:.65rem;padding:0;margin:0;list-style:none}.simulation-content li{display:flex;align-items:center;gap:.7rem;padding:.7rem;border:1px solid var(--line);border-radius:9px;color:var(--text-dim);font-size:.8rem}.simulation-content li b{display:grid;place-items:center;flex:none;width:1.6rem;height:1.6rem;border-radius:50%;background:var(--panel-2);font-size:.7rem}.simulation-content li.current{border-color:var(--signal);color:var(--text);background:color-mix(in srgb,var(--signal) 7%,var(--panel))}.simulation-content li.current b,.simulation-content li.done b{background:var(--signal);color:#fff}.simulation-content li.done{color:var(--text)}.simulation-result{display:grid;gap:.2rem;margin-top:1rem;padding:.8rem;border:1px dashed color-mix(in srgb,var(--signal) 55%,var(--line));border-radius:9px;background:color-mix(in srgb,var(--signal) 5%,var(--panel))}.simulation-result strong{font-size:.75rem}.simulation-result span{color:var(--text-dim);font-size:.72rem;line-height:1.45}.simulation-content footer{display:flex;justify-content:space-between;gap:.6rem;margin-top:1rem}@media(max-width:650px){.simulation-backdrop{padding:.35rem}.simulation-dialog{width:100%;max-height:96dvh}.simulation-layout{grid-template-columns:135px minmax(0,1fr)}.simulation-nav{padding:.35rem}.simulation-option{font-size:.64rem;padding:.35rem}.simulation-content{padding:1rem .75rem}.simulation-content li{align-items:flex-start;font-size:.72rem}.simulation-header{padding:.85rem}.simulation-header p{max-width:36ch}}
</style>
